const UNITS=['Item','Hour','KM','Day','m²','Litre','Kg','Job','Quantity','Custom'];
const METHODS=['Flat Rate','Per Item','Per Hour','Per Kilometre','Per Day','Per m²','Per Litre','Per Kg','Custom Quantity','Vehicle / Fuel'];
const DEFAULT={margin:20,contingency:5,minimumCharge:0,gstRate:15,billableHours:100,validityDays:14,costingPrefix:'JC',quotePrefix:'QUO',quoteTerms:'This quote is valid for {validityDays} days from the quote date.',overheadBasis:'billable',quoteDesign:{template:'classic',title:'QUOTE',accent:'#1976bd',customerHeading:'Customer',dateHeading:'Quote date',descriptionHeading:'Description',amountHeading:'Amount ex GST',subtotalLabel:'Subtotal',gstLabel:'GST',totalLabel:'Total',termsHeading:'Terms',defaultNote:'Thank you for the opportunity to provide this quotation.',showLogo:true,showBank:true,advanceEnabled:false,advancePercent:50,advanceLabel:'Advance required'},overheads:[],labourRoles:[{name:'General Labour',rate:30,isDefault:true,notes:'',active:true}],variableRates:[],presets:[{name:'Materials',unit:'Item',unitCost:0,notes:'',active:true}]};
