function settings(){return business()?.settings||{}} function toast(s){const t=$('toast');if(t){t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2800)}else alert(s)}
function loadCfg(){const old=settings().jobCostingSettings||{};cfg={...DEFAULT,...old};cfg.quoteDesign={...DEFAULT.quoteDesign,...(old.quoteDesign||{})};if(old.labourRate&&!old.labourRoles)cfg.labourRoles=[{name:'General Labour',rate:num(old.labourRate),isDefault:true,notes:'Migrated from previous default labour rate',active:true}];cfg.overheads=Array.isArray(cfg.overheads)?cfg.overheads:[];cfg.labourRoles=Array.isArray(cfg.labourRoles)?cfg.labourRoles:[];cfg.variableRates=Array.isArray(cfg.variableRates)?cfg.variableRates:[];cfg.presets=Array.isArray(cfg.presets)?cfg.presets:[]}
function cleanPrefix(v,f='X'){return String(v||f).trim().replace(/[^A-Za-z0-9]/g,'').toUpperCase()||f} function fmt(p,n){return `${cleanPrefix(p)}-${String(n).padStart(4,'0')}`}
async function nextNumber(table,col,prefix){const c=client();if(!c)return fmt(prefix,1);const {data}=await c.from(table).select(col).order('created_at',{ascending:false}).limit(500);let max=0,re=new RegExp('^'+cleanPrefix(prefix).replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'-(\\d+)$','i');for(const x of data||[]){const m=String(x[col]||'').match(re);if(m)max=Math.max(max,+m[1]||0)}return fmt(prefix,max+1)}
function billing(c){const a=Array.isArray(c?.contacts)?c.contacts:[];return a.find(x=>x.billing)||a[0]||{}} async function customers(){const {data,error}=await client().from('customers').select('*').order('name');if(error)return[];return data||[]} async function refreshCustomers(){const a=await customers();$('jcCustomerOptions').innerHTML=a.map(c=>`<option value="${esc(c.name)}"></option>`).join('')} async function selectCustomer(name){const a=await customers(),c=a.find(x=>String(x.name).trim().toLowerCase()===String(name||'').trim().toLowerCase());customerId=c?.id||null;if(c&&(!$('jcAddress').value||!$('jcAddress').dataset.touched))$('jcAddress').value=c.address||'';$('jcCustomerHint').textContent=c?`${c.customer_number||''}${billing(c).email?' · '+billing(c).email:''}`:'Customer not found — click Create Customer to add them.';return c}
