function monthlyOverhead(){return cfg.overheads.filter(x=>x.active!==false).reduce((s,x)=>s+monthlyEquivalent(x),0)} function overheadRate(){return cfg.billableHours>0?monthlyOverhead()/cfg.billableHours:0}
function renderActiveOverheads(t){const box=$('jcActiveOverheads');if(!box)return;const active=cfg.overheads.filter(x=>x.active!==false);if(!active.length){box.innerHTML='<span class="hint">No active business overheads.</span>';return}const hours=num(cfg.billableHours);box.innerHTML=active.map(x=>{const monthly=monthlyEquivalent(x),allocated=hours>0?t.basis*(monthly/hours):0;return `<div class="jc-overhead-item"><span>${esc(x.name||'Overhead')}</span><small>${money(monthly)}/mo</small><strong>${money(allocated)}</strong></div>`}).join('')}
function totals(){const labourCost=labour.reduce((s,x)=>s+num(x.hours)*num(x.workers||1)*num(x.rate),0),billable=labour.reduce((s,x)=>s+num(x.hours)*num(x.workers||1),0);let fuel=0,otherVar=0;variables.forEach(x=>{const v=num(x.qty)*num(x.rate);if(x.method==='Vehicle / Fuel'||x.isFuel)fuel+=v;else otherVar+=v});const directCost=direct.reduce((s,x)=>s+num(x.qty)*num(x.unitCost),0),basis=cfg.overheadBasis==='duration'?num($('jcDuration')?.value):billable,overhead=basis*overheadRate(),subtotal=labourCost+fuel+otherVar+directCost+overhead,contPct=Math.max(0,num($('jcContingency')?.value??cfg.contingency)),cont=subtotal*contPct/100,trueCost=subtotal+cont,margin=Math.min(99.99,Math.max(0,num($('jcMargin')?.value??cfg.margin))),calc=trueCost>0?trueCost/(1-margin/100):0,recommended=Math.max(calc,num(cfg.minimumCharge)),quote=Math.max(0,num($('jcQuotePrice')?.value)),profit=quote-trueCost,actualMargin=quote>0?profit/quote*100:0,gst=quote*num(cfg.gstRate)/100;return{labourCost,billable,fuel,otherVar,directCost,basis,overhead,subtotal,contPct,cont,trueCost,margin,calc,recommended,quote,profit,actualMargin,gst,total:quote+gst}}
function recalc(){const t=totals();[['jcLabourTotal',t.labourCost],['jcFuelTotal',t.fuel],['jcVariableTotal',t.otherVar],['jcDirectTotal',t.directCost],['jcOverheadTotal',t.overhead],['jcSubtotal',t.subtotal],['jcContingencyTotal',t.cont],['jcTrueCost',t.trueCost],['jcRecommended',t.recommended],['jcMinimum',cfg.minimumCharge],['jcQuoteDisplay',t.quote],['jcProfit',t.profit],['jcQuoteGst',t.gst],['jcQuoteTotal',t.total]].forEach(([id,v])=>$(id).textContent=money(v));$('jcMarginDisplay').textContent=t.margin.toFixed(2).replace(/\.00$/,'')+'%';$('jcActualMargin').textContent=t.actualMargin.toFixed(2)+'%';$('jcContingencyLabel').textContent=`Contingency (${t.contPct}%)`;$('jcGstLabel').textContent=`GST (${num(cfg.gstRate)}%)`;$('jcOverheadMethod').textContent=`Allocation: ${cfg.overheadBasis==='duration'?'Job Duration Hours':'Total Billable Labour Hours'} (${t.basis.toFixed(2)} h × ${money(overheadRate())}/h)`;renderActiveOverheads(t);if(!$('jcQuotePrice').dataset.touched)$('jcQuotePrice').value=t.recommended?t.recommended.toFixed(2):''}
function roleOptions(sel=''){return cfg.labourRoles.filter(x=>x.active!==false).map(x=>`<option value="${esc(x.name)}" ${x.name===sel?'selected':''}>${esc(x.name)}</option>`).join('')}
function updateRowTotal(el,value){const row=el?.closest?.('.jc-cost-row');const out=row?.querySelector?.('strong');if(out)out.textContent=money(value)}
function renderLabour(){const r=$('jcLabourRows');r.innerHTML='<div class="jc-row-head jc-labour-head"><span>Role</span><span>Hours</span><span>Workers</span><span>Cost / hour</span><span>Total</span><span></span></div>'+labour.map((x,i)=>`<div class="jc-cost-row jc-labour-row"><select data-jl="${i}" data-k="role"><option value="">Custom role</option>${roleOptions(x.role)}</select><input type="number" min="0" step="0.25" data-jl="${i}" data-k="hours" value="${num(x.hours)}"><input type="number" min="0" step="1" data-jl="${i}" data-k="workers" value="${num(x.workers||1)}"><input type="number" min="0" step="0.01" data-jl="${i}" data-k="rate" value="${num(x.rate)}"><strong>${money(num(x.hours)*num(x.workers||1)*num(x.rate))}</strong><button class="remove" data-jlr="${i}">×</button></div>`).join('');r.querySelectorAll('[data-jl]').forEach(e=>{const handler=ev=>{let x=labour[+ev.target.dataset.jl],k=ev.target.dataset.k;if(k==='role'){x.role=ev.target.value;let role=cfg.labourRoles.find(z=>z.name===x.role);if(role)x.rate=num(role.rate);renderLabour();recalc();return}x[k]=num(ev.target.value);updateRowTotal(ev.target,num(x.hours)*num(x.workers||1)*num(x.rate));recalc()};e.oninput=handler;e.onchange=handler});r.querySelectorAll('[data-jlr]').forEach(b=>b.onclick=()=>{labour.splice(+b.dataset.jlr,1);renderLabour();recalc()})}
function variableOptions(sel=''){return cfg.variableRates.map((x,i)=>x.active!==false?`<option value="${i}" ${String(i)===String(sel)?'selected':''}>${esc(x.name)}</option>`:'').join('')}
function renderVariables(){const r=$('jcVariableRows');r.innerHTML='<div class="jc-row-head jc-variable-head"><span>Variable rate</span><span>Quantity</span><span>Unit</span><span>Rate</span><span>Total</span><span></span></div>'+variables.map((x,i)=>`<div class="jc-cost-row jc-variable-row"><select data-jv="${i}" data-k="preset"><option value="">Manual variable cost</option>${variableOptions(x.preset)}</select><input type="number" min="0" step="0.01" data-jv="${i}" data-k="qty" value="${num(x.qty)}"><input data-jv="${i}" data-k="unit" value="${esc(x.unit||'Unit')}" readonly><input type="number" min="0" step="0.0001" data-jv="${i}" data-k="rate" value="${num(x.rate)}"><strong>${money(num(x.qty)*num(x.rate))}</strong><button class="remove" data-jvr="${i}">×</button></div>`).join('');r.querySelectorAll('[data-jv]').forEach(e=>{const handler=ev=>{let x=variables[+ev.target.dataset.jv],k=ev.target.dataset.k;if(k==='preset'){x.preset=ev.target.value;let p=cfg.variableRates[+x.preset];if(p){x.name=p.name;x.method=p.method;x.unit=p.unit;x.rate=variableRate(p);x.isFuel=p.method==='Vehicle / Fuel'}renderVariables();recalc();return}else if(k!=='unit')x[k]=num(ev.target.value);updateRowTotal(ev.target,num(x.qty)*num(x.rate));recalc()};e.oninput=handler;e.onchange=handler});r.querySelectorAll('[data-jvr]').forEach(b=>b.onclick=()=>{variables.splice(+b.dataset.jvr,1);renderVariables();recalc()})}
function variableRate(p){if(p.method==='Vehicle / Fuel'){const base=num(p.fuelPrice)/(num(p.fuelEconomy)||1);return base*(1+num(p.fuelContingency)/100)}return num(p.rate)}
