function renderFields(){const r=$('jcCustomFields');r.innerHTML=fields.map((x,i)=>`<div class="custom-field-row"><input data-jf="${i}" data-k="label" value="${esc(x.label||'')}" placeholder="Field name"><input data-jf="${i}" data-k="value" value="${esc(x.value||'')}" placeholder="Value"><button class="remove" data-jfr="${i}">×</button></div>`).join('')||'<p class="hint">No additional fields added.</p>';r.querySelectorAll('[data-jf]').forEach(e=>e.oninput=ev=>fields[+ev.target.dataset.jf][ev.target.dataset.k]=ev.target.value);r.querySelectorAll('[data-jfr]').forEach(b=>b.onclick=()=>{fields.splice(+b.dataset.jfr,1);renderFields()})}
async function fresh(){costingId=customerId=null;$('jcNumber').value=await nextNumber('job_costings','costing_number',cfg.costingPrefix);$('jcDate').value=iso();['jcCustomerName','jcDescription','jcAddress','jcNotes'].forEach(id=>$(id).value='');$('jcDuration').value='';$('jcMargin').value=cfg.margin;$('jcContingency').value=cfg.contingency;$('jcQuotePrice').value='';delete $('jcQuotePrice').dataset.touched;if($('jcAdvanceEnabled'))$('jcAdvanceEnabled').checked=quoteDesign().advanceEnabled===true;if($('jcAdvancePercent'))$('jcAdvancePercent').value=num(quoteDesign().advancePercent||50);
  // v27+: a new costing is a business-specific template. Every ACTIVE setting is preloaded.
  labour=cfg.labourRoles.filter(x=>x.active!==false).map(x=>({role:x.name||'',hours:0,workers:1,rate:num(x.rate)}));
  variables=cfg.variableRates.map((x,i)=>x.active!==false?{preset:String(i),name:x.name||'',method:x.method||'Flat Rate',qty:0,unit:x.unit||'Unit',rate:variableRate(x),isFuel:x.method==='Vehicle / Fuel'}:null).filter(Boolean);
  direct=cfg.presets.filter(x=>x.active!==false).map(x=>({description:x.name||'',qty:0,unit:x.unit||'Item',unitCost:num(x.unitCost)}));
  fields=[];renderLabour();renderVariables();renderDirect();renderFields();recalc();refreshCustomers()}
