function validate(){if(!customerId)return toast('Select an existing customer from My Customers.'),false;if(!$('jcDescription').value.trim())return toast('Enter a job name / description.'),false;if(num($('jcMargin').value)>=100)return toast('Target Gross Margin must be less than 100%.'),false;if(cfg.overheads.some(x=>x.active!==false)&&num(cfg.billableHours)<=0)return toast('Estimated Billable Hours Per Month must be greater than zero when overhead allocation is enabled.'),false;return true}
async function saveCosting(silent=false){if(!validate())return null;let p=payload(),row={...p};delete row.id;let r=costingId?await client().from('job_costings').update(row).eq('id',costingId).select().single():await client().from('job_costings').insert(row).select().single();if(r.error)return toast('Could not save costing: '+r.error.message),null;costingId=r.data.id;if(!silent)toast('Job costing saved to the cloud.');return r.data}
async function loadCosting(id,duplicate=false){const {data,error}=await client().from('job_costings').select('*').eq('id',id).single();if(error)return toast(error.message);costingId=duplicate?null:data.id;customerId=data.customer_id;$('jcNumber').value=duplicate?await nextNumber('job_costings','costing_number',cfg.costingPrefix):data.costing_number;$('jcDate').value=duplicate?iso():data.costing_date;$('jcCustomerName').value=data.customer_name||'';$('jcDescription').value=data.job_description||'';$('jcAddress').value=data.job_address||'';$('jcDuration').value=num(data.job_duration_hours)||'';$('jcNotes').value=data.notes||'';let snap=data.costing_snapshot||{};$('jcMargin').value=num(snap.settings?.margin??data.margin_percent??cfg.margin);$('jcContingency').value=num(snap.settings?.contingency??data.contingency_percent??cfg.contingency);$('jcQuotePrice').value=num(data.proposed_quote_price_ex_gst)||'';$('jcQuotePrice').readOnly=false;$('jcQuotePrice').disabled=false;$('jcQuotePrice').dataset.touched='1';if($('jcAdvanceEnabled'))$('jcAdvanceEnabled').checked=snap.settings?.advanceEnabled??quoteDesign().advanceEnabled??false;if($('jcAdvancePercent'))$('jcAdvancePercent').value=num(snap.settings?.advancePercent??quoteDesign().advancePercent??50);labour=Array.isArray(snap.labour)?snap.labour:(data.labour_items||[]);variables=Array.isArray(snap.variables)?snap.variables:(data.variable_costs||[]);direct=Array.isArray(snap.direct)?snap.direct:(data.direct_costs||[]);fields=Array.isArray(snap.fields)?snap.fields:(data.custom_fields||[]);renderLabour();renderVariables();renderDirect();renderFields();recalc();showTab('costing');if(duplicate)toast('Costing duplicated. Review it and save as a new costing.')}
async function renderSaved(){let {data,error}=await client().from('job_costings').select('*').order('created_at',{ascending:false});if(error)return;let q=String($('jcSavedSearch').value||'').toLowerCase();data=(data||[]).filter(x=>!q||[x.costing_number,x.customer_name,x.job_description].join(' ').toLowerCase().includes(q));$('jcSavedRows').innerHTML=data.map(x=>`<tr><td>${esc(x.costing_date)}</td><td><strong>${esc(x.costing_number)}</strong></td><td>${esc(x.customer_name)}</td><td>${esc(x.job_description)}</td><td>${money(x.total_cost_ex_gst)}</td><td>${money(x.recommended_price_ex_gst)}</td><td>${money(x.proposed_quote_price_ex_gst)}</td><td><div class="row-actions"><button class="secondary" data-e="${x.id}">Edit</button><button class="secondary" data-d="${x.id}">Duplicate</button><button class="secondary" data-q="${x.id}">Quote</button><button class="danger" data-x="${x.id}">Delete</button></div></td></tr>`).join('')||'<tr><td colspan="8">No saved costings found.</td></tr>';let r=$('jcSavedRows');r.querySelectorAll('[data-e]').forEach(b=>b.onclick=()=>loadCosting(b.dataset.e));r.querySelectorAll('[data-d]').forEach(b=>b.onclick=()=>loadCosting(b.dataset.d,true));r.querySelectorAll('[data-q]').forEach(b=>b.onclick=async()=>{await loadCosting(b.dataset.q);createQuote()});r.querySelectorAll('[data-x]').forEach(b=>b.onclick=async()=>{if(confirm('Delete this saved job costing?')){let {error}=await client().from('job_costings').delete().eq('id',b.dataset.x);if(error)toast(error.message);else renderSaved()}})}
