function quoteDesign(){return {...DEFAULT.quoteDesign,...(cfg.quoteDesign||{})}} function defaultBank(){const a=settings().bankAccounts||[];return a.find(x=>x.isDefault)||a[0]||{name:'',account:''}} function quoteItems(q){let a=Array.isArray(q?.quote_items)?q.quote_items:[];return a.length?a:[{description:q?.description||'Service / job description',qty:1,unit_price:num(q?.quoted_price_ex_gst),total:num(q?.quoted_price_ex_gst)}]} function quoteAdvance(q,total){const d=quoteDesign(),has=Object.prototype.hasOwnProperty.call(q||{},'advance_enabled'),enabled=has?q?.advance_enabled===true:d.advanceEnabled===true,pct=Math.max(0,Math.min(100,num(Object.prototype.hasOwnProperty.call(q||{},'advance_percent')?q.advance_percent:d.advancePercent)));return{enabled,pct,amount:enabled?(num(q?.advance_amount)||total*pct/100):0}}
