async function makePdf(q,out='save'){
 const jsPDF=window.jspdf?.jsPDF;
 if(!jsPDF)return toast('PDF library unavailable.');
 if(!window.html2canvas)return toast('Quote renderer unavailable. Please refresh and try again.');

 // v39: generate the quote PDF from the exact same HTML renderer used by
 // the live quotation preview and customer-facing quote preview.
 const host=document.createElement('div');
 host.className='quote-pdf-render-host';
 host.innerHTML=quotePreviewMarkup(q);
 const sheet=host.firstElementChild;
 if(!sheet)return toast('Could not render quote.');
 sheet.classList.add('quote-pdf-sheet');
 document.body.appendChild(host);

 try{
  const imgs=[...sheet.querySelectorAll('img')];
  await Promise.all(imgs.map(img=>img.complete?Promise.resolve():new Promise(resolve=>{img.onload=img.onerror=()=>resolve()})));
  if(document.fonts?.ready)await document.fonts.ready;

  const canvas=await window.html2canvas(sheet,{
   scale:2,
   backgroundColor:'#ffffff',
   useCORS:true,
   logging:false,
   imageTimeout:5000,
   scrollX:0,
   scrollY:0,
   windowWidth:sheet.scrollWidth,
   windowHeight:sheet.scrollHeight
  });

  const doc=new jsPDF({unit:'mm',format:'a4',orientation:'portrait'});
  const pageW=210,pageH=297,margin=10,usableW=pageW-margin*2,usableH=pageH-margin*2;
  const pxPerMm=canvas.width/usableW;
  const pagePxH=Math.floor(usableH*pxPerMm);
  let srcY=0,page=0;

  while(srcY<canvas.height){
   const sliceH=Math.min(pagePxH,canvas.height-srcY);
   const slice=document.createElement('canvas');
   slice.width=canvas.width;
   slice.height=sliceH;
   const ctx=slice.getContext('2d');
   ctx.fillStyle='#fff';ctx.fillRect(0,0,slice.width,slice.height);
   ctx.drawImage(canvas,0,srcY,canvas.width,sliceH,0,0,canvas.width,sliceH);
   const img=slice.toDataURL('image/jpeg',0.96);
   const imgH=sliceH/pxPerMm;
   if(page>0)doc.addPage();
   doc.addImage(img,'JPEG',margin,margin,usableW,imgH,undefined,'FAST');
   srcY+=sliceH;page++;
  }

  const fn=`${q.quote_number}.pdf`;
  if(out==='blob')return{blob:doc.output('blob'),base64:doc.output('datauristring').split(',')[1],filename:fn};
  doc.save(fn);
  return{filename:fn};
 }finally{
  host.remove();
 }
}
async function sendQuote(q){let to=String(q.customer_email||'').trim();if(!to)return toast('Customer does not have a billing email.');let pdf=await makePdf(q,'blob'),{error}=await client().functions.invoke('send-quote',{body:{quoteId:q.id,to,pdfBase64:pdf.base64,filename:pdf.filename}});if(error)return toast('Quote email failed: '+error.message);await client().from('quotes').update({status:q.status==='draft'?'sent':q.status,last_sent_to:to,last_sent_at:new Date().toISOString()}).eq('id',q.id);toast('Quote emailed successfully.');renderQuotes();openQuote(q.id)}
