async function openQuickQuote(){quickCustomerId=null;quickItems=[{description:'',qty:1,unit_price:0,total:0}];$('qqNumber').value=await nextNumber('quotes','quote_number',cfg.quotePrefix);$('qqDate').value=iso();$('qqValid').value=new Date(Date.now()+cfg.validityDays*86400000).toISOString().slice(0,10);$('qqCustomer').value='';$('qqCustomerHint').textContent='Linked to My Customers.';$('qqGst').value=num(cfg.gstRate);$('qqAdvanceEnabled').checked=quoteDesign().advanceEnabled===true;$('qqAdvancePercent').value=num(quoteDesign().advancePercent||50);$('qqNotes').value=quoteDesign().defaultNote||'';$('qqTerms').value=String(cfg.quoteTerms).replaceAll('{validityDays}',String(cfg.validityDays));const a=await customers();$('qqCustomerOptions').innerHTML=a.map(c=>`<option value="${esc(c.name)}"></option>`).join('');renderQuickItems();updateQuickTotals();$('quickQuoteModal').classList.add('open')}
async function saveQuickQuote(){let c=await quickSelectCustomer();if(!c)return toast('Select an existing customer or create one first.');let items=quickItems.filter(x=>String(x.description||'').trim()&&num(x.qty)>0).map(x=>({...x,total:num(x.qty)*num(x.unit_price)}));if(!items.length)return toast('Add at least one quote item.');let sub=items.reduce((s,x)=>s+x.total,0),g=Math.max(0,num($('qqGst').value)),gst=sub*g/100,total=sub+gst,enabled=$('qqAdvanceEnabled').checked,pct=Math.max(0,Math.min(100,num($('qqAdvancePercent').value))),bc=billing(c);let row={job_costing_id:null,quote_number:$('qqNumber').value,quote_date:$('qqDate').value,valid_until:$('qqValid').value||null,customer_id:c.id,customer_name:c.name,customer_address:c.address||'',customer_email:bc.email||'',description:items[0].description,quote_items:items,quoted_price_ex_gst:sub,gst_rate:g,gst_amount:gst,total_incl_gst:total,advance_enabled:enabled,advance_percent:pct,advance_amount:enabled?total*pct/100:0,notes:$('qqNotes').value.trim(),terms:$('qqTerms').value.trim(),status:'draft',updated_at:new Date().toISOString()};let {data,error}=await client().from('quotes').insert(row).select().single();if(error)return toast('Could not create quote: '+error.message);$('quickQuoteModal').classList.remove('open');toast(`Quote ${data.quote_number} created.`);renderQuotes();openQuote(data.id)}
function activeCheckbox(x,i,k,prefix){return `<label class="inline-check"><input type="checkbox" data-${prefix}="${i}" data-k="${k}" ${x[k]!==false?'checked':''}> Active</label>`}
function renderOverheads(){let r=$('jcOverheadRows');r.innerHTML=cfg.overheads.map((x,i)=>`<div class="jc-setting-card"><div class="settings-row"><input data-jo="${i}" data-k="name" value="${esc(x.name||'')}" placeholder="Cost name"><input type="number" min="0" step=".01" data-jo="${i}" data-k="amount" value="${num(x.amount)}" placeholder="Amount ex GST"><select data-jo="${i}" data-k="frequency">${['Weekly','Monthly','Quarterly','Annual','Custom'].map(v=>`<option ${x.frequency===v?'selected':''}>${v}</option>`).join('')}</select><input data-jo="${i}" data-k="notes" value="${esc(x.notes||'')}" placeholder="Notes">${activeCheckbox(x,i,'active','jo')}<button class="danger" data-jor="${i}">Delete</button></div></div>`).join('')||'<p class="hint">No business overheads added.</p>';bindCfgRows(r,'jo',cfg.overheads,renderOverheads);updateOverheadSummary()}
function renderRoles(){let r=$('jcRoleRows');r.innerHTML=cfg.labourRoles.map((x,i)=>`<div class="jc-setting-card"><div class="settings-row"><input data-jr="${i}" data-k="name" value="${esc(x.name||'')}" placeholder="Role name"><input type="number" min="0" step=".01" data-jr="${i}" data-k="rate" value="${num(x.rate)}" placeholder="Loaded cost/hour"><label class="inline-check"><input type="checkbox" data-jr="${i}" data-k="isDefault" ${x.isDefault?'checked':''}> Default</label><input data-jr="${i}" data-k="notes" value="${esc(x.notes||'')}" placeholder="Notes">${activeCheckbox(x,i,'active','jr')}<button class="danger" data-jrr="${i}">Delete</button></div></div>`).join('')||'<p class="hint">No labour roles added.</p>';bindCfgRows(r,'jr',cfg.labourRoles,renderRoles)}
function renderVariableRates(){let r=$('jcVariableRateRows');r.innerHTML=cfg.variableRates.map((x,i)=>`<div class="jc-setting-card"><div class="settings-row variable-setting"><input data-jvrate="${i}" data-k="name" value="${esc(x.name||'')}" placeholder="Name"><select data-jvrate="${i}" data-k="method">${METHODS.map(v=>`<option ${x.method===v?'selected':''}>${v}</option>`).join('')}</select><input data-jvrate="${i}" data-k="unit" value="${esc(x.unit||'Unit')}" placeholder="Unit"><input type="number" min="0" step=".0001" data-jvrate="${i}" data-k="rate" value="${num(x.rate)}" placeholder="Rate"><input data-jvrate="${i}" data-k="notes" value="${esc(x.notes||'')}" placeholder="Notes">${activeCheckbox(x,i,'active','jvrate')}<button class="danger" data-jvrater="${i}">Delete</button></div>${x.method==='Vehicle / Fuel'?`<div class="fuel-settings"><label>Fuel Price / L<input type="number" min="0" step=".01" data-jvrate="${i}" data-k="fuelPrice" value="${num(x.fuelPrice)}"></label><label>Vehicle km / L<input type="number" min="0" step=".01" data-jvrate="${i}" data-k="fuelEconomy" value="${num(x.fuelEconomy)}"></label><label>Fuel Contingency %<input type="number" min="0" step=".1" data-jvrate="${i}" data-k="fuelContingency" value="${num(x.fuelContingency)}"></label><div><small>Calculated cost / km</small><strong>${money(variableRate(x))}</strong></div></div>`:''}</div>`).join('')||'<p class="hint">No variable rates added.</p>';bindCfgRows(r,'jvrate',cfg.variableRates,renderVariableRates)}
function renderPresets(){let r=$('jcPresetRows');r.innerHTML=cfg.presets.map((x,i)=>`<div class="jc-setting-card"><div class="settings-row"><input data-jp="${i}" data-k="name" value="${esc(x.name||'')}" placeholder="Description"><select data-jp="${i}" data-k="unit">${UNITS.map(v=>`<option ${x.unit===v?'selected':''}>${v}</option>`).join('')}</select><input type="number" min="0" step=".01" data-jp="${i}" data-k="unitCost" value="${num(x.unitCost)}" placeholder="Default unit cost"><input data-jp="${i}" data-k="notes" value="${esc(x.notes||'')}" placeholder="Notes">${activeCheckbox(x,i,'active','jp')}<button class="danger" data-jpr="${i}">Delete</button></div></div>`).join('')||'<p class="hint">No cost presets added.</p>';bindCfgRows(r,'jp',cfg.presets,renderPresets)}
function bindCfgRows(r,prefix,arr,rerender){r.querySelectorAll(`[data-${prefix}]`).forEach(e=>{let fn=ev=>{let x=arr[+ev.target.dataset[prefix]],k=ev.target.dataset.k;x[k]=ev.target.type==='checkbox'?ev.target.checked:(ev.target.type==='number'?num(ev.target.value):ev.target.value);if(k==='isDefault'&&x[k])arr.forEach((z,j)=>{if(j!==+ev.target.dataset[prefix])z.isDefault=false});if(k==='method'||k==='frequency'||k==='isDefault')rerender();updateOverheadSummary()};e.onchange=fn;if(!['SELECT','INPUT'].includes(e.tagName)||e.type!=='checkbox')e.oninput=fn});r.querySelectorAll(`[data-${prefix}r]`).forEach(b=>b.onclick=()=>{arr.splice(+b.dataset[prefix+'r'],1);rerender()})}
function updateOverheadSummary(){$('jcMonthlyOverhead').textContent=money(monthlyOverhead());$('jcOverheadRate').textContent=money(overheadRate())}
function renderSettings(){loadCfg();$('jcSetMargin').value=cfg.margin;$('jcSetContingency').value=cfg.contingency;$('jcSetMinimum').value=cfg.minimumCharge;$('jcSetGst').value=cfg.gstRate;$('jcSetBillable').value=cfg.billableHours;$('jcSetValidity').value=cfg.validityDays;$('jcSetCostingPrefix').value=cfg.costingPrefix;$('jcSetQuotePrefix').value=cfg.quotePrefix;$('jcSetOverheadBasis').value=cfg.overheadBasis;$('jcSetQuoteTerms').value=cfg.quoteTerms;const d=quoteDesign();$('jcQuoteTemplate').value=d.template||'classic';$('jcQuoteTitle').value=d.title;$('jcQuoteAccent').value=d.accent;$('jcQuoteCustomerHeading').value=d.customerHeading;$('jcQuoteDateHeading').value=d.dateHeading;$('jcQuoteDescriptionHeading').value=d.descriptionHeading;$('jcQuoteAmountHeading').value=d.amountHeading;$('jcQuoteSubtotalLabel').value=d.subtotalLabel;$('jcQuoteGstLabel').value=d.gstLabel;$('jcQuoteTotalLabel').value=d.totalLabel;$('jcQuoteTermsHeading').value=d.termsHeading;$('jcQuoteAdvanceLabel').value=d.advanceLabel||'Advance required';$('jcQuoteAdvancePercent').value=num(d.advancePercent||50);$('jcQuoteAdvanceEnabled').checked=d.advanceEnabled===true;$('jcQuoteDefaultNote').value=d.defaultNote;$('jcQuoteShowLogo').checked=d.showLogo!==false;$('jcQuoteShowBank').checked=d.showBank!==false;renderOverheads();renderRoles();renderVariableRates();renderPresets();renderQuoteDesignPreview()}
async function saveSettings(){let margin=num($('jcSetMargin').value),bill=num($('jcSetBillable').value);if(margin>=100)return toast('Target Gross Margin must be less than 100%.');if(cfg.overheads.some(x=>x.active!==false)&&bill<=0)return toast('Estimated Billable Hours Per Month must be greater than zero.');syncQuoteDesignFromForm();cfg={...cfg,margin,contingency:num($('jcSetContingency').value),minimumCharge:num($('jcSetMinimum').value),gstRate:num($('jcSetGst').value),billableHours:bill,validityDays:Math.max(1,Math.floor(num($('jcSetValidity').value)||14)),costingPrefix:cleanPrefix($('jcSetCostingPrefix').value,'JC'),quotePrefix:cleanPrefix($('jcSetQuotePrefix').value,'QUO'),overheadBasis:$('jcSetOverheadBasis').value,quoteTerms:$('jcSetQuoteTerms').value.trim()};let all={...settings(),jobCostingSettings:cfg};let {error}=await client().from('businesses').update({settings:all,updated_at:new Date().toISOString()}).eq('id',business().id);if(error)return toast(error.message);business().settings=all;toast('Job costing settings saved.');fresh()}
function showSettingsTab(n){document.querySelectorAll('[data-jcs-tab]').forEach(b=>b.classList.toggle('active',b.dataset.jcsTab===n));document.querySelectorAll('.jcs-panel').forEach(p=>p.classList.toggle('active',p.id==='jcs-'+n));if(n==='quote-design')renderQuoteDesignPreview()}
function showTab(n){document.querySelectorAll('[data-jc-tab]').forEach(b=>b.classList.toggle('active',b.dataset.jcTab===n));document.querySelectorAll('.jc-panel').forEach(p=>p.classList.toggle('active',p.id==='jc-panel-'+n));if(n==='saved')renderSaved();if(n==='quotes')renderQuotes();if(n==='settings')renderSettings()}
function bind(){document.querySelectorAll('[data-jc-tab]').forEach(b=>b.onclick=()=>showTab(b.dataset.jcTab));document.querySelectorAll('[data-jcs-tab]').forEach(b=>b.onclick=()=>showSettingsTab(b.dataset.jcsTab));['jcQuoteTemplate','jcQuoteTitle','jcQuoteAccent','jcQuoteCustomerHeading','jcQuoteDateHeading','jcQuoteDescriptionHeading','jcQuoteAmountHeading','jcQuoteSubtotalLabel','jcQuoteGstLabel','jcQuoteTotalLabel','jcQuoteTermsHeading','jcQuoteAdvanceLabel','jcQuoteAdvancePercent','jcQuoteAdvanceEnabled','jcQuoteDefaultNote','jcQuoteShowLogo','jcQuoteShowBank'].forEach(id=>{const el=$(id);if(el){el.oninput=syncQuoteDesignFromForm;el.onchange=syncQuoteDesignFromForm}});$('jcNewCostingTop').onclick=async()=>{await fresh();showTab('costing')};$('jcAddLabour').onclick=()=>{let d=cfg.labourRoles.find(x=>x.active!==false&&x.isDefault)||cfg.labourRoles.find(x=>x.active!==false);labour.push({role:d?.name||'',hours:0,workers:1,rate:num(d?.rate)});renderLabour()};$('jcAddVariable').onclick=()=>{variables.push({preset:'',name:'',method:'Flat Rate',qty:1,unit:'Unit',rate:0});renderVariables()};$('jcAddCost').onclick=()=>{direct.push({description:'',qty:1,unit:'Item',unitCost:0});renderDirect()};$('jcAddField').onclick=()=>{fields.push({label:'',value:''});renderFields()};['jcMargin','jcContingency','jcDuration'].forEach(id=>$(id).oninput=()=>{if(id==='jcMargin')delete $('jcQuotePrice').dataset.touched;recalc()});$('jcQuotePrice').oninput=()=>{$('jcQuotePrice').dataset.touched='1';recalc()};$('jcAddress').oninput=()=>{$('jcAddress').dataset.touched='1'};$('jcCustomerName').onchange=e=>selectCustomer(e.target.value);$('jcCustomerName').onblur=e=>selectCustomer(e.target.value);$('jcCreateCustomer').onclick=()=>{if(typeof window.openCustomerEditor!=='function')return toast('Customer editor is unavailable.');window.openCustomerEditor(null,{name:$('jcCustomerName').value.trim(),address:$('jcAddress').value.trim(),contacts:[]})};window.addEventListener('customer:saved',async e=>{const c=e.detail;if(!c)return;await refreshCustomers();if($('quickQuoteModal')?.classList.contains('open')){$('qqCustomer').value=c.name||'';quickCustomerId=c.id;$('qqCustomerHint').textContent=`${c.customer_number||''}${billing(c).email?' · '+billing(c).email:''} · Customer created`}else{$('jcCustomerName').value=c.name||'';customerId=c.id||null;if(c.address&&!$('jcAddress').dataset.touched)$('jcAddress').value=c.address;$('jcCustomerHint').textContent=`${c.customer_number||''}${billing(c).email?' · '+billing(c).email:''} · Customer created`}});$('jcSaveCosting').onclick=()=>saveCosting();$('jcCreateQuote').onclick=createQuote;$('jcClearCosting').onclick=fresh;$('jcSavedSearch').oninput=renderSaved;$('jcSavedRefresh').onclick=renderSaved;$('jcQuoteSearch').oninput=renderQuotes;$('jcQuoteStatusFilter').onchange=renderQuotes;$('jcQuoteRefresh').onclick=renderQuotes;$('jcQuickQuote').onclick=openQuickQuote;$('closeQuickQuoteModal').onclick=()=>$('quickQuoteModal').classList.remove('open');$('qqCancel').onclick=()=>$('quickQuoteModal').classList.remove('open');$('qqAddItem').onclick=()=>{quickItems.push({description:'',qty:1,unit_price:0,total:0});renderQuickItems();updateQuickTotals()};$('qqCustomer').onchange=quickSelectCustomer;$('qqCustomer').onblur=quickSelectCustomer;$('qqCreateCustomer').onclick=()=>{if(typeof window.openCustomerEditor!=='function')return toast('Customer editor is unavailable.');window.openCustomerEditor(null,{name:$('qqCustomer').value.trim(),contacts:[]})};['qqGst','qqAdvancePercent'].forEach(id=>$(id).oninput=updateQuickTotals);$('qqAdvanceEnabled').onchange=updateQuickTotals;$('qqSave').onclick=saveQuickQuote;$('jcAddOverhead').onclick=()=>{cfg.overheads.push({name:'',amount:0,frequency:'Monthly',notes:'',active:true});renderOverheads()};$('jcAddRole').onclick=()=>{cfg.labourRoles.push({name:'',rate:0,isDefault:false,notes:'',active:true});renderRoles()};$('jcAddVariableRate').onclick=()=>{cfg.variableRates.push({name:'',method:'Flat Rate',unit:'Job',rate:0,notes:'',active:true});renderVariableRates()};$('jcAddPreset').onclick=()=>{cfg.presets.push({name:'',unit:'Item',unitCost:0,notes:'',active:true});renderPresets()};$('jcSetBillable').oninput=()=>{cfg.billableHours=num($('jcSetBillable').value);updateOverheadSummary()};$('jcSaveSettings').onclick=saveSettings;$('closeQuoteModal').onclick=()=>$('quoteModal').classList.remove('open');$('quoteModal').onclick=e=>{if(e.target===$('quoteModal'))$('quoteModal').classList.remove('open')}}
async function onShow(){refreshCustomers();if(!$('jcNumber').value)await fresh()} function init(){loadCfg();bind();refreshCustomers();fresh()} window.JobCosting={init,onShow,showTab,renderQuotes};
